export const SUITS=['♠','♥','♣','♦'];
export const label=r=>({11:'J',12:'Q',13:'K',14:'A'}[r]||String(r));
export const magic={2:['RESET','A fresh start. Anything goes.'],8:['GHOST','See-through. The previous rule stays.'],9:['UNDERCUT','Play on anything. Next non-8 card: 9 or lower.'],10:['INFERNO','Burn the pile. Take another turn.']};
export function deck(extra=0){let d=[];for(let s=0;s<4;s++)for(let r=2;r<=14;r++)d.push({r,s,id:`${s}-${r}`});for(let i=0;i<extra;i++)d.push({r:[2,8,9,10][i%4],s:i%4,id:`extra-${i}`});for(let i=d.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[d[i],d[j]]=[d[j],d[i]]}return d}
export function rule(pile){for(let i=pile.length-1;i>=0;i--){let r=pile[i].r;if(r===8)continue;if(r===2||r===10)return {r:0,low:false};return {r,low:r===9}}return {r:0,low:false}}
export function legal(c,pile){if([2,8,9,10].includes(c.r))return true;let t=rule(pile);return !t.r||(t.low?c.r<=9:c.r>=t.r)}
export function source(p){return p.hand.length?'hand':p.face.length?'face':'blind'}
export function burned(pile){if(!pile.length)return false;if(pile.at(-1).r===10)return true;return pile.length>=4&&pile.slice(-4).every(c=>c.r===pile.at(-1).r)}
export function valid(cards,pile){let p=[...pile];for(let i=0;i<cards.length;i++){let c=cards[i],prev=cards[i-1];if(i){if(burned(p))return false;if(!(c.r===prev.r||(c.s===prev.s&&c.r===prev.r+1)))return false;}if(!legal(c,p)&&!(i&&c.s===prev.s&&c.r===prev.r+1))return false;p.push(c)}return cards.length>0}
export function deal(round=1,extra=0,min=3){let d=deck(extra),player={hand:[],face:[],blind:[]},house={hand:[],face:[],blind:[]};for(let p of [player,house]){p.blind=d.splice(0,3);p.face=d.splice(0,3);p.hand=d.splice(0,min)}return {round,player,house,deck:d,pile:[],burns:0,cardsBurned:0,playerBurns:0,playerPickups:0,turn:'player',moves:0,ended:false}}
export function replenish(g,p,min=3){while(p.hand.length<min&&g.deck.length)p.hand.push(g.deck.pop())}
export function options(g,who){let p=g[who],src=source(p);if(src==='blind')return p.blind.length?[[p.blind[0]]]:[];let cards=p[src],out=[];for(let c of cards){if(!legal(c,g.pile))continue;let chain=[c];out.push([...chain]);for(let j=0;j<cards.length;j++){let next=cards.find(x=>!chain.includes(x)&&valid([...chain,x],g.pile));if(!next)break;chain.push(next);out.push([...chain])}}return out}
export function play(g,who,ids,min=3,protect=false){let p=g[who],src=source(p),cards=ids.map(id=>p[src].find(c=>c.id===id));if(!cards.length||cards.some(c=>!c)||new Set(ids).size!==ids.length)return {error:'Choose your cards first.'};if(src!=='blind'&&!valid(cards,g.pile))return {error:'Start with a playable card. Link equal ranks or consecutive cards of one suit.'};if(src==='blind'&&cards.length!==1)return {error:'One blind card at a time.'};p[src]=p[src].filter(c=>!ids.includes(c.id));g.moves++;if(src==='blind'&&!legal(cards[0],g.pile)){if(protect){return {protected:true,cards,src}}p.hand.push(...g.pile,...cards);if(who==='player')g.playerPickups=(g.playerPickups||0)+1;g.pile=[];g.turn=who==='player'?'house':'player';return {pickup:true,cards,src}}
g.pile.push(...cards);let burn=burned(g.pile),size=g.pile.length,burnedCards=burn?[...g.pile]:[];if(burn){g.pile=[];g.burns++;g.cardsBurned=(g.cardsBurned||0)+size;if(who==='player')g.playerBurns=(g.playerBurns||0)+1}replenish(g,p,min);if(!p.hand.length&&!p.face.length&&!p.blind.length){g.ended=true;g.winner=who}g.turn=burn?who:who==='player'?'house':'player';return {cards,burn,size,src,burnedCards}}
export function pickup(g,who){if(g.ended||g.turn!==who||!g.pile.length||options(g,who).length)return false;if(who==='player')g.playerPickups=(g.playerPickups||0)+1;g[who].hand.push(...g.pile);g.pile=[];g.turn=who==='player'?'house':'player';g.moves++;return true}
